	/** 
	 * updating a System_.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a System_." );

		StringBuilder msg = new StringBuilder( "Failed to update a System_ : " );        
		System_ entity = read();
		UpdateSystem_Command command = generateUpdateCommand();
		command.setSystem_Id(entity.getSystem_Id());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created System_." );

			// for use later on...
			system_Id = entity.getSystem_Id();

			System_Service proxy = System_Service.getSystem_Instance();  

			proxy.updateSystem_( command ).get();

			LOGGER.info( "-- Successfully saved System_ - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + system_Id + " : command -" +  command + " : " + e );

			throw e;
		}
	}

